def _to_half(x):
    """Return integer if whole, else half-integer (x.5)."""
    hx = 2 * x
    if abs(hx - round(hx)) < 1e-9:
        v = int(round(hx))
        if v % 2 == 0:
            return v // 2
        return v / 2.0
    return x

